#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


TOTAL_STAGES=12

# Run from the repository root whatever directory it was invoked from — the
# seed and deploy scripts below are relative paths, and so is the env file.
cd "$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# NOT the dev `.env`. This wizard captures production credentials and must never
# write them over the ones this laptop develops against. `.env.*` is gitignored,
# so this file stays out of the repository — it holds the production database
# password, the Upstash URL and CRON_SECRET in plaintext, which is the price of
# being re-runnable. Delete it once the cutover is done if you would rather not
# keep it.
ENV_FILE="${ZAMMY_PROD_ENV_FILE:-deploy/vercel/.env.production}"
CA_CERT_FILE="deploy/vercel/prod-ca.crt"

# ── Local helpers, on top of the library above ────────────────────────────

# dev_env KEY — the value of KEY in the DEVELOPMENT .env, if there is one. Used
# only to offer a sensible default for keys production shares with the laptop
# (the Currents and Gemini keys are one account each, not one per environment).
dev_env() {
  [[ -f .env ]] || return 0
  local line; line=$(grep -E "^${1}=" .env | tail -n1) || return 0
  local value="${line#*=}"
  value="${value%\"}"; value="${value#\"}"
  printf '%s' "$value"
}

# vercel_env NAME VALUE — set NAME on the PRODUCTION environment, idempotently.
# `vercel env add` refuses a name that already exists, so the remove comes
# first and its failure is expected on the first run.
vercel_env() {
  local name="$1" value="$2"
  vercel env rm "$name" production --yes >/dev/null 2>&1 || true
  if printf '%s' "$value" | vercel env add "$name" production >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel production env %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel production env $name")
    warn "failed to set $name — set it by hand: vercel env add $name production"
  fi
}

# check_url VALUE PORT LABEL — the two shapes that have each cost a deploy
# cycle on this project: the wrong pooler port, and a ?sslmode= that
# @zammy/config refuses outright.
check_url() {
  local value="$1" port="$2" label="$3"
  case "$value" in
    *"sslmode="*)
      warn "$label carries ?sslmode= — strip it. @zammy/config refuses a Postgres URL that sets it,"
      note "  because node-postgres then silently ignores DATABASE_SSL."
      return 1 ;;
  esac
  case "$value" in
    *":$port/"*) return 0 ;;
    *) warn "$label should be on port $port. Check you copied the right pooler."; return 1 ;;
  esac
}

banner "zammy — production cutover (VERCEL-ALL-IN-SCOPE Phase 5)"

# ──────────────────────────────────────────────────────────────────────────
stage "Preflight — the tools this needs"
# ──────────────────────────────────────────────────────────────────────────
say "Nothing is created in this stage; it only checks what the later ones assume."
missing=0
for tool in vercel docker rsync curl openssl; do
  if command -v "$tool" >/dev/null 2>&1; then
    step "$tool — found"
  else
    warn "$tool — MISSING"; missing=1
  fi
done
if vercel whoami >/dev/null 2>&1; then
  step "vercel — logged in as $(vercel whoami 2>/dev/null | tail -n1)"
else
  warn "vercel — not logged in. Run \`vercel login\` and start again."; missing=1
fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  step "gh — authenticated (stage 9 can set the Actions secrets for you)"
else
  warn "gh — not ready. Stage 9 will print the secrets for you to set by hand."
fi
if docker inspect zammy-postgres-1 >/dev/null 2>&1; then
  step "the dev corpus container is up (stage 8 dumps from it)"
else
  warn "zammy-postgres-1 is not running — \`pnpm infra:up\` before stage 8."
fi
[[ "$missing" == "0" ]] || { printf '\n'; warn "fix the above first."; exit 1; }
pause "All good — continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "Supabase — create the production project"
# ──────────────────────────────────────────────────────────────────────────
say "A dedicated Supabase project for production. (There used to be a second,"
say "free-tier preview pair here too — retired 2026-08-26, since Upstash allows"
say "only one Redis database per project and previews needed one of their own"
say "or none at all. Just this one project now.)"
open_url "https://supabase.com/dashboard/new"
step "Name it 'zammy-production'."
step "Region: East US (North Virginia) — us-east-1."
note "  Vercel Hobby deploys to iad1, which is us-east-1 — stay in-region."
step "Generate a strong database password and SAVE IT in your password manager."
note "  Supabase shows it once. It is embedded in both connection strings below,"
note "  so losing it means resetting it and re-running stages 3, 7 and 9."
step "Wait for the project to finish provisioning (~2 minutes)."
pause "Project is ready?"

# ──────────────────────────────────────────────────────────────────────────
stage "Supabase — the two connection strings"
# ──────────────────────────────────────────────────────────────────────────
say "Two URLs, two ports, two different jobs. Getting them the wrong way round"
say "boots green and fails later: the migrator's advisory lock is session-scoped"
say "and a pin borrowed from the transaction pooler is not a pin to a backend."
open_url "https://supabase.com/dashboard/project/_/settings/database"
step "Click 'Connect' (top of the dashboard), then the 'Connection string' tab."
step "Copy the TRANSACTION pooler URI — port 6543. This is the app's."
step "Strip any '?sslmode=...' from the end before pasting."
# Bounded. An unbounded re-ask loop spins forever when stdin is closed — a
# wizard run from anything other than a terminal would hang rather than fail.
attempts=0
while :; do
  ask DATABASE_URL "Transaction pooler URI (6543):"
  check_url "$DATABASE_URL" 6543 "DATABASE_URL" && break
  attempts=$((attempts + 1))
  [[ "$attempts" -lt 5 ]] || { warn "five attempts without a valid value — stopping."; exit 1; }
done
step "Copy the SESSION pooler URI — port 5432. Migrations and the seed use this."
attempts=0
while :; do
  ask DATABASE_SESSION_URL "Session pooler URI (5432):"
  check_url "$DATABASE_SESSION_URL" 5432 "DATABASE_SESSION_URL" && break
  attempts=$((attempts + 1))
  [[ "$attempts" -lt 5 ]] || { warn "five attempts without a valid value — stopping."; exit 1; }
done
write_env DATABASE_URL "$DATABASE_URL"
write_env DATABASE_SESSION_URL "$DATABASE_SESSION_URL"

# ──────────────────────────────────────────────────────────────────────────
stage "Supabase — the CA certificate"
# ──────────────────────────────────────────────────────────────────────────
say "DATABASE_SSL=verify-full is what the code sets, and verify-full without a"
say "CA to verify against is just a connection that fails."
open_url "https://supabase.com/dashboard/project/_/settings/database"
step "Scroll to 'SSL Configuration' and click 'Download certificate'."
step "It lands in your Downloads folder as prod-ca-*.crt."
attempts=0
while :; do
  ask CERT_PATH "Path to the downloaded .crt:"
  CERT_PATH="${CERT_PATH/#\~/$HOME}"
  if [[ -f "$CERT_PATH" ]] && grep -q "BEGIN CERTIFICATE" "$CERT_PATH"; then break; fi
  warn "that is not a readable PEM certificate — try again."
  attempts=$((attempts + 1))
  [[ "$attempts" -lt 5 ]] || { warn "five attempts without a valid value — stopping."; exit 1; }
done
cp "$CERT_PATH" "$CA_CERT_FILE"
printf '  %s✓ copied%s the certificate to %s\n' "$GREEN" "$RESET" "$CA_CERT_FILE"
note "  Kept as a FILE rather than an env value: a PEM is multi-line and would"
note "  break a KEY=value file. Stages 7 and 9 read it from here."

# ──────────────────────────────────────────────────────────────────────────
stage "Upstash — the production Redis database"
# ──────────────────────────────────────────────────────────────────────────
say "Redis carries the burst window, the per-IP counters, the ingest pending"
say "ledger and the fill cache."
open_url "https://console.upstash.com/redis"
step "Create database → name 'zammy-production', region us-east-1 (N. Virginia)."
step "Leave TLS enabled — it is the default and it is not optional here."
step "Open the database, then the 'Connect' panel, and copy the redis:// URL."
say ""
warn "It MUST start with rediss:// — two s's."
note "  A plaintext redis:// URL validates, boots, serves /healthz, and only then"
note "  fails at /readyz with \"Stream isn't writeable\". Upstash is TLS-only."
attempts=0
while :; do
  ask_secret REDIS_URL "Upstash URL (rediss://…):"
  case "$REDIS_URL" in
    rediss://*) break ;;
    *) warn "that does not start with rediss:// — copy the TLS URL." ;;
  esac
  attempts=$((attempts + 1))
  [[ "$attempts" -lt 5 ]] || { warn "five attempts without a valid value — stopping."; exit 1; }
done
write_env REDIS_URL "$REDIS_URL"

# ──────────────────────────────────────────────────────────────────────────
stage "The application secrets"
# ──────────────────────────────────────────────────────────────────────────
say "One generated, three carried over from the laptop."
CRON_SECRET="$(openssl rand -hex 32)"
step "CRON_SECRET — generated."
note "  It gates /api/chores, /api/drain AND /api/keepalive, all fail-closed:"
note "  leaving it unset does not open them, it disables them — including the"
note "  guard that keeps the database off Supabase's 7-day pause."
note "  You will paste this into Supabase Vault in stage 11."
write_env CRON_SECRET "$CRON_SECRET"
say ""
step "The Currents and Gemini keys are one account each, not one per environment."
CURRENTS_API_KEY="$(dev_env CURRENTS_API_KEY)"
GEMINI_API_KEY="$(dev_env GEMINI_API_KEY)"
CURRENTS_USER_AGENT="$(dev_env CURRENTS_USER_AGENT)"
[[ -n "$CURRENTS_API_KEY" ]] && note "  CURRENTS_API_KEY — taken from the dev .env" || ask_secret CURRENTS_API_KEY "CURRENTS_API_KEY:"
[[ -n "$GEMINI_API_KEY" ]]   && note "  GEMINI_API_KEY   — taken from the dev .env" || ask_secret GEMINI_API_KEY "GEMINI_API_KEY:"
[[ -n "$CURRENTS_USER_AGENT" ]] && note "  CURRENTS_USER_AGENT — taken from the dev .env" || ask CURRENTS_USER_AGENT "CURRENTS_USER_AGENT:"
write_env CURRENTS_API_KEY "$CURRENTS_API_KEY"
write_env GEMINI_API_KEY "$GEMINI_API_KEY"
write_env CURRENTS_USER_AGENT "$CURRENTS_USER_AGENT"
pause "Continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "Push the production environment to Vercel"
# ──────────────────────────────────────────────────────────────────────────
say "Sixteen variables. @zammy/config defaults the other fifty of .env.example,"
say "and hand-setting fifty defaults is fifty chances at the typo that boots green."
say ""
if ! confirm "Write these to the Vercel PRODUCTION environment now?"; then
  warn "skipped — re-run this wizard when you are ready."
  exit 0
fi
vercel_env DATABASE_URL          "$DATABASE_URL"
vercel_env DATABASE_SESSION_URL  "$DATABASE_SESSION_URL"
vercel_env DATABASE_SSL          "verify-full"
vercel_env DATABASE_CA_CERT      "$(cat "$CA_CERT_FILE")"
vercel_env DATABASE_POOL_MAX     "2"
vercel_env REDIS_URL             "$REDIS_URL"
# The default is bullmq, and leaving it there publishes to a Redis queue that
# nothing on Vercel drains — a silent, total loss of background ingest.
vercel_env INGEST_QUEUE_DRIVER   "vercel"
vercel_env CRON_SECRET           "$CRON_SECRET"
# 75 labels is the entire 300 s maxDuration at GEMINI_MAX_RPM=15.
vercel_env CHORE_MAX_LABELS      "50"
vercel_env CURRENTS_MODE         "live"
vercel_env CURRENTS_API_KEY      "$CURRENTS_API_KEY"
vercel_env CURRENTS_USER_AGENT   "$CURRENTS_USER_AGENT"
vercel_env GEMINI_API_KEY        "$GEMINI_API_KEY"
# Measured on the spike: Fastify sees 127.0.0.1 with the real client one hop out.
vercel_env TRUSTED_PROXY_HOPS    "1"
vercel_env LOG_LEVEL             "info"
vercel_env ENABLE_EXPERIMENTAL_COREPACK "1"
say ""
note "CORS_ORIGIN is deliberately not set yet — the origin does not exist until"
note "the deployment does. Stage 12 sets it and redeploys."
pause "Continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "Seed production from the dev corpus"
# ──────────────────────────────────────────────────────────────────────────
say "A 24 MB custom-format dump of ~32,000 articles, restored through the"
say "session pooler. Measured at a few seconds end to end."
say ""
say "This is ONE-TIME setup, not a repeatable sync. The script refuses a target"
say "that already has tables, so a second run is a safe no-op rather than a"
say "restore layered on top of existing rows."
say ""
if confirm "Seed the production database now?"; then
  ./deploy/vercel/seed-production.sh "$DATABASE_SESSION_URL"
  say ""
  step "Verifying the migration ledger came with it…"
  DATABASE_SESSION_URL="$DATABASE_SESSION_URL" \
  DATABASE_SSL=verify-full \
  DATABASE_CA_CERT="$(cat "$CA_CERT_FILE")" \
    pnpm db:migrate
  note "  'Nothing to migrate' is the expected line. Anything else means the"
  note "  restore and the code's schema disagree — stop rather than deploy over it."
else
  SKIPPED+=("seeding production (./deploy/vercel/seed-production.sh \"\$DATABASE_SESSION_URL\")")
  warn "skipped."
fi
pause "Continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub Actions secrets — the migration job"
# ──────────────────────────────────────────────────────────────────────────
say "ci.yml's 'migrate (production)' job reads these. It fails loudly on a"
say "missing one rather than running against no URL."
set_secret PRODUCTION_DATABASE_SESSION_URL "$DATABASE_SESSION_URL"
set_secret SUPABASE_CA_CERT "$(cat "$CA_CERT_FILE")"
say ""
note "There is no PREVIEW_DATABASE_SESSION_URL secret and no 'migrate (preview)'"
note "job. The preview data plane was retired 2026-08-26 — Upstash allows only"
note "one Redis database per project. See ADR-0015 and deploy/vercel/README.md."
pause "Continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "The first production deploy"
# ──────────────────────────────────────────────────────────────────────────
say "deploy.sh copies the tree with .git excluded and builds from the copy."
say "Vercel stamps a deployment with the COMMIT AUTHOR, and this repository's"
say "author is not the Vercel account — a deploy from the repository itself"
say "lands BLOCKED, rendered as UNKNOWN, with no logs to explain it."
say ""
if confirm "Deploy to production now?"; then
  ./deploy/vercel/deploy.sh --prod
else
  SKIPPED+=("the production deploy (./deploy/vercel/deploy.sh --prod)")
  warn "skipped."
fi
say ""
warn "What you need next is the STABLE PRODUCTION ALIAS, not the URL deploy.sh"
warn "just printed."
note "  deploy.sh prints the per-DEPLOYMENT URL — zammy-<hash>.vercel.app — which"
note "  names one immutable deployment and nothing else. It is fine for a health"
note "  probe and wrong for everything durable: the same value goes into Supabase"
note "  Vault as zammy_base_url in the next stage, and cron pinned to a specific"
note "  deployment keeps hitting that one after every later deploy. Nothing"
note "  complains — the old deployment answers, against whatever environment it"
note "  was built with, until it is eventually pruned."
say ""
step "Find the alias — it is the one that does NOT change between deploys:"
say "    vercel inspect <the URL deploy.sh printed>    # see the 'Aliases' section"
say "  or the dashboard: Project → Settings → Domains."
say "  On a fresh project it is usually https://zammy.vercel.app."
say ""
attempts=0
while :; do
  ask PRODUCTION_URL "The stable production alias (https://…):"
  if [[ "$PRODUCTION_URL" == https://* ]]; then
    # A CLI deployment URL is `<project>-<9-char hash>-<scope>.vercel.app`, and
    # the hash segment is what distinguishes it from the alias. Catching the
    # obvious shape is worth it; this is the value cron will live on.
    if [[ "$PRODUCTION_URL" =~ ^https://[a-z0-9-]+-[a-z0-9]{9}(-[a-z0-9-]+)?\.vercel\.app/?$ ]]; then
      warn "that looks like a per-deployment URL (it carries a hash segment)."
      note "  Use the alias, or paste it again to override if you are sure."
      ask CONFIRM_URL "Paste it again to use it anyway, or the alias:"
      if [[ "$CONFIRM_URL" == "$PRODUCTION_URL" ]]; then break; fi
      PRODUCTION_URL="$CONFIRM_URL"
      continue
    fi
    break
  fi
  warn "that does not start with https:// — paste the full origin."
  attempts=$((attempts + 1))
  [[ "$attempts" -lt 5 ]] || { warn "five attempts without a valid value — stopping."; exit 1; }
done
PRODUCTION_URL="${PRODUCTION_URL%/}"
write_env PRODUCTION_URL "$PRODUCTION_URL"
step "Probing /readyz twice — the first read is a cold start and can lose the"
step "race with Upstash's ~800 ms handshake, so only the second one counts."
curl -s "$PRODUCTION_URL/readyz" || true; printf '\n'
curl -s "$PRODUCTION_URL/readyz" || true; printf '\n'
note "  ready = both reachable · degraded = Redis is not · unready = Postgres is not"
pause "Continue?"

# ──────────────────────────────────────────────────────────────────────────
stage "Supabase Cron — schedule the chores and the pause guard"
# ──────────────────────────────────────────────────────────────────────────
say "This is the step that has never been run against any project. Until it is,"
say "no nightly pass fires and nothing keeps the database off the 7-day pause."
open_url "https://supabase.com/dashboard/project/_/sql/new"
step "Open deploy/vercel/supabase-cron.sql and paste the WHOLE file in."
step "Before running it, uncomment the two vault.create_secret lines near the"
step "top and substitute these two values:"
say ""
printf "    select vault.create_secret('%s', 'zammy_cron_secret');\n" "$CRON_SECRET"
printf "    select vault.create_secret('%s', 'zammy_base_url');\n" "$PRODUCTION_URL"
say ""
warn "Run those two lines ONCE. Re-running creates a second secret of the same name."
step "Run the script. It creates pg_cron + pg_net, the helper function, and four"
step "jobs: retention 03:00 UTC, storylines 04:00 UTC, keep-alive 12:00 UTC, drain every 10 min."
say ""
step "Then check they registered:"
say "    select jobname, schedule, active from cron.job order by jobname;"
pause "Four jobs listed?"
say ""
say "A 202 is not evidence a pass ran — the route answers before the work starts."
say "chore_runs is the record. Tomorrow morning:"
say "    pnpm chores status"

# ──────────────────────────────────────────────────────────────────────────
stage "DNS — zammy.info"
# ──────────────────────────────────────────────────────────────────────────
say "Last stage, and the only one this machine has no credentials for."
open_url "https://vercel.com/ashaharudin1/zammy/settings/domains"
step "Add 'zammy.info', and 'www.zammy.info' if you want it."
step "Vercel will show the exact DNS records to create. Copy what IT shows —"
step "the values are per-project and change; do not use a remembered IP."
say ""
step "Open your registrar's DNS panel and add those records."
note "  The TLS key for zammy.info already on this machine lives in ~/zammy-tls,"
note "  outside the repo. Vercel issues its own certificate, so you should not"
note "  need it — but do not delete it on the strength of this deploy."
pause "Records added and Vercel shows 'Valid Configuration'?"
say ""
step "Last thing: point CORS_ORIGIN at the real origin and redeploy."
ask CORS_ORIGIN "The production origin (e.g. https://zammy.info):"
write_env CORS_ORIGIN "$CORS_ORIGIN"
vercel_env CORS_ORIGIN "$CORS_ORIGIN"
warn "An env var change does not reach a deployment that already exists."
if confirm "Redeploy production so it picks up CORS_ORIGIN?"; then
  ./deploy/vercel/deploy.sh --prod
else
  SKIPPED+=("the redeploy that picks up CORS_ORIGIN (./deploy/vercel/deploy.sh --prod)")
fi

finish

cat <<'CLOSING'
  What is now true, and what to check tomorrow:

    - `pnpm chores status` answers "did last night's chores run?" from chore_runs.
      A row with finished_at IS NULL is a pass that never came back — most likely
      the label pass hitting the 300 s maxDuration.
    - There is NO label backlog riding along with the corpus. Every one of the
      5,253 promoted storylines has been offered to a model (measured
      2026-08-26). What `pnpm chores status` reports as 373 is the "asked and
      unnameable" count — storylines a model declined to name, which are not
      owed another attempt until their coverage doubles. A raw `label is null`
      count reads 934 and is misleading: 562 of those are merged-away aliases,
      which are not storylines and cannot hold a label at all.
    - deploy/vercel/.env.production holds production credentials in plaintext.
      It is gitignored. Delete it if you would rather not keep it — this wizard
      re-reads it on a re-run, and that is all it is for.

CLOSING
